# pythonFunction.py
# Writes a SymPy expression (matrix) into a Python file as a function,
# in the same way as matlabFunction(...,'file',...) in MATLAB.
#
#   pythonFunction(expr, 'MlocQ4', [X, rho, Lz])
#   -> writes MlocQ4.py with  def MlocQ4(in1, rho, Lz)
# A vector argument (sympy Matrix) is called in1, in2, ... as in MATLAB.

import sympy as sp

def pythonFunction(expr, funcname, vars):
    expr = sp.Matrix(expr)
    lines = [f'# {funcname}.py',
             '# This function was generated by pythonFunction (SymPy), see the run_Derive... file.',
             '', 'import numpy as np', '']
    argnames = []
    unpack = []
    nvec = 0
    for v in vars:
        if isinstance(v, sp.MatrixBase):
            nvec += 1
            name = f'in{nvec}'
            argnames.append(name)
            unpack.append(f'    {name} = np.asarray({name}, dtype=float).ravel()')
            for i, s in enumerate(v):
                unpack.append(f'    {s} = {name}[{i}]')
        else:
            argnames.append(str(v))
    lines.append(f'def {funcname}({", ".join(argnames)}):')
    lines += unpack
    # common subexpressions as t1, t2, ... (cf. MATLAB t2, t3, ...)
    reps, red = sp.cse(expr, symbols=sp.numbered_symbols('t'))
    for s, e in reps:
        lines.append(f'    {s} = {sp.pycode(e).replace("math.", "np.")}')
    M = red[0]
    rows = []
    for i in range(M.shape[0]):
        rows.append('[' + ', '.join(sp.pycode(M[i, j]).replace('math.', 'np.') for j in range(M.shape[1])) + ']')
    lines.append('    out = np.array([' + ',\n                    '.join(rows) + '], dtype=float)')
    lines.append('    return out')
    lines.append('')
    with open(funcname + '.py', 'w') as f:
        f.write('\n'.join(lines))
